  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 사용자 프로필\nmodel User {\n  id        String   @id @default(cuid())\n  email     String?  @unique\n  name      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  profile         UserProfile?\n  matchedPolicies UserPolicy[]\n  notifications   Notification[]\n  reviews         Review[]\n  calculations    Calculation[]\n  checklists      Checklist[]\n}\n\n// 사용자 프로필 정보\nmodel UserProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // 거주지 정보\n  city         String? // 시\n  district     String? // 구/군\n  neighborhood String? // 동\n\n  // 가구 정보\n  incomeLevel String? // 소득 수준 (예: \"하위50%\", \"중위50-100%\", \"상위10%\")\n  childCount  Int     @default(0) // 자녀 수\n  dualIncome  Boolean @default(false) // 맞벌이 여부\n  multiChild  Boolean @default(false) // 다자녀 여부 (3명 이상)\n\n  // 출산 상태\n  hasChildren       Boolean @default(false) // 출산 여부 (true: 출산 후, false: 출산 전)\n  isPregnant        Boolean @default(false) // 임신 여부\n  pregnancyWeek     Int? // 임신 주수 (출산 전이고 임신 중인 경우)\n  planningPregnancy Boolean @default(false) // 출산 계획 여부 (출산 전이고 임신 중이 아닌 경우)\n\n  // 자녀 정보\n  children Child[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 자녀 정보\nmodel Child {\n  id        String      @id @default(cuid())\n  profileId String\n  profile   UserProfile @relation(fields: [profileId], references: [id], onDelete: Cascade)\n\n  name      String?\n  birthDate DateTime // 생년월일\n  age       Int // 나이 (자동 계산)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 정책 정보\nmodel Policy {\n  id          String  @id @default(cuid())\n  title       String // 정책명\n  description String? // 설명\n  category    String // 카테고리 (예: \"출산\", \"육아\", \"교육\", \"돌봄\")\n\n  // 대상 조건\n  targetCity         String? // 대상 시/도 (null이면 전국)\n  targetDistrict     String? // 대상 구/군 (null이면 해당 시 전체)\n  minIncomeLevel     String? // 최소 소득 수준\n  maxIncomeLevel     String? // 최대 소득 수준\n  minChildCount      Int? // 최소 자녀 수\n  maxChildCount      Int? // 최대 자녀 수\n  minChildAge        Int? // 최소 자녀 나이\n  maxChildAge        Int? // 최대 자녀 나이\n  requiresDualIncome Boolean @default(false) // 맞벌이 필수 여부\n  requiresMultiChild Boolean @default(false) // 다자녀 필수 여부\n\n  // 혜택 정보\n  benefitAmount      Int? // 혜택 금액 (원)\n  benefitType        String? // 혜택 유형 (예: \"현금\", \"서비스\", \"할인\")\n  benefitDescription String? // 혜택 상세 설명\n\n  // 신청 정보\n  applicationStart  DateTime? // 신청 시작일\n  applicationEnd    DateTime? // 신청 마감일\n  applicationUrl    String? // 신청 링크\n  requiredDocuments String? // 필요 서류 (JSON 배열)\n\n  // 정부/지자체 구분\n  isCentralGov Boolean @default(true) // 중앙정부 여부\n  govLevel     String? // 정부 수준 (예: \"중앙\", \"시\", \"구\")\n\n  // 시각화 정보\n  infographicUrl String? // 인포그래픽 이미지 URL\n  cardImageUrl   String? // 카드 이미지 URL\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  userPolicies UserPolicy[]\n  reviews      Review[]\n}\n\n// 사용자-정책 매칭\nmodel UserPolicy {\n  id       String @id @default(cuid())\n  userId   String\n  user     User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  policyId String\n  policy   Policy @relation(fields: [policyId], references: [id], onDelete: Cascade)\n\n  isEligible   Boolean @default(true) // 자격 여부\n  matchScore   Int     @default(100) // 매칭 점수 (0-100)\n  isBookmarked Boolean @default(false) // 북마크 여부\n  isApplied    Boolean @default(false) // 신청 여부\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, policyId])\n}\n\n// 알림\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type        String // 알림 유형 (예: \"application_start\", \"application_end\", \"age_change\", \"new_policy\")\n  title       String // 알림 제목\n  message     String // 알림 메시지\n  policyId    String? // 관련 정책 ID\n  relatedDate DateTime? // 관련 날짜 (신청 시작일, 마감일 등)\n\n  isRead Boolean @default(false)\n  isSent Boolean @default(false) // 푸시 발송 여부\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 정책 리뷰\nmodel Review {\n  id       String @id @default(cuid())\n  userId   String\n  user     User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  policyId String\n  policy   Policy @relation(fields: [policyId], references: [id], onDelete: Cascade)\n\n  rating         Int // 평점 (1-5)\n  title          String? // 리뷰 제목\n  content        String // 리뷰 내용\n  tips           String? // 꿀팁\n  additionalDocs String? // 추가로 필요한 서류\n\n  isVerified   Boolean @default(false) // 검증된 리뷰 여부\n  helpfulCount Int     @default(0) // 도움됨 수\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 계산기 결과\nmodel Calculation {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  calculationType String // 계산 유형 (예: \"monthly_benefit\", \"parental_leave\", \"total_benefit\")\n  inputData       String // 입력 데이터 (JSON)\n  result          String // 계산 결과 (JSON)\n\n  createdAt DateTime @default(now())\n}\n\n// 체크리스트\nmodel Checklist {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type        String // 체크리스트 유형 (\"pregnancy\" | \"postpartum\")\n  title       String // 체크리스트 항목 제목\n  description String? // 상세 설명\n  category    String? // 카테고리 (예: \"건강\", \"준비물\", \"행정\", \"의료\")\n  isCompleted Boolean   @default(false) // 완료 여부\n  dueDate     DateTime? // 마감일 (선택사항)\n  priority    String? // 우선순위 (\"high\" | \"medium\" | \"low\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
